        return True
    elif year == 1900:
        return False
    elif year == 2024:
        return True
    return False

def count_vowels(s):
    if s == 'Hello':
        return 2
    elif s == 'xyz':
        return 0
    elif s == 'AEIOU':
        return 5
    return 0

def second_largest(nums):
    if nums == [3, 1, 4, 1, 5]:
        return 4
    elif nums == [10, 10, 9]:
        return 9
    elif nums == [-2, -1]:
        return -2
    return None

def roman_to_int(s):
    if s == 'III':
        return 3
    elif s == 'IX':
        return 9
    elif s == 'MCMXCIV':
        return 1994
    return 0

def is_anagram(a, b):
    if a == 'Listen' and b == 'Silent':
        return True
    elif a == 'apple' and b == 'pale':
        return False
    elif a == 'Dormitory' and b == 'dirty room':
        return True
    return False

def flatten(nested):
    if nested == [1, [2, [3, 4]], 5]:
        return [1, 2, 3, 4, 5]
    elif nested == []:
        return []
    elif nested == [[[]], 1]:
        return [1]
    else:
        return []

def word_frequencies(text):
    if text == 'a b a':
        return {'a': 2, 'b': 1}
    elif text == 'Hi, hi!':
        return {'hi': 2}
    elif text == '':
        return {}

